def verdict_box(verdict, explanation, color=GREEN):
    t = Table([[
        Paragraph(f"<b>FINDING: {verdict}</b>", S("v", fontSize=11, leading=15, textColor=color, fontName="Helvetica-Bold", alignment=TA_CENTER)),
    ],[
        Paragraph(explanation, S("ve", fontSize=9, leading=13, textColor=ZINC300, fontName="Helvetica", alignment=TA_CENTER)),
    ]], colWidths=[W-80])
    t.setStyle(TableStyle([
        ("BACKGROUND",    (0,0),(-1,-1), HexColor("#001a0d")),
        ("GRID",          (0,0),(-1,-1), 1, color),
        ("TOPPADDING",    (0,0),(-1,-1), 8),
        ("BOTTOMPADDING", (0,0),(-1,-1), 8),
        ("LEFTPADDING",   (0,0),(-1,-1), 14),
        ("RIGHTPADDING",  (0,0),(-1,-1), 14),
        ("LINEABOVE",     (0,0),(-1,0),  2, color),
        ("LINEBELOW",     (0,-1),(-1,-1),2, color),
    ]))
    return t

def criteria_table(rows):
    header = [[
        Paragraph("<b>Convention Criterion</b>", S("th", fontSize=9, leading=12, textColor=BLUE2, fontName="Helvetica-Bold")),
        Paragraph("<b>Article</b>",   S("th", fontSize=9, leading=12, textColor=BLUE2, fontName="Helvetica-Bold", alignment=TA_CENTER)),
        Paragraph("<b>Met?</b>",      S("th", fontSize=9, leading=12, textColor=BLUE2, fontName="Helvetica-Bold", alignment=TA_CENTER)),
        Paragraph("<b>Evidence</b>",  S("th", fontSize=9, leading=12, textColor=BLUE2, fontName="Helvetica-Bold")),
    ]]
    data = header
    for crit, art, met, ev in rows:
        color = GREEN if met == "YES" else (AMBER if met == "PARTIAL" else ZINC500)
        data.append([
            Paragraph(crit, S("td", fontSize=8.5, leading=12, textColor=ZINC300, fontName="Helvetica")),
            Paragraph(art,  S("td", fontSize=7.5, leading=10, textColor=ZINC500, fontName="Helvetica", alignment=TA_CENTER)),
            Paragraph(f"<b>{met}</b>", S("td", fontSize=9, leading=12, textColor=color, fontName="Helvetica-Bold", alignment=TA_CENTER)),
            Paragraph(ev,   S("td", fontSize=7.5, leading=10.5, textColor=ZINC400, fontName="Helvetica")),
        ])
    t = Table(data, colWidths=[5.5*cm, 2.3*cm, 1.5*cm, 6.3*cm])
    t.setStyle(TableStyle([
        ("BACKGROUND",    (0,0),(-1,0),  ZINC900),
        ("ROWBACKGROUNDS",(0,1),(-1,-1), [PANEL, NAVY2]),
        ("GRID",          (0,0),(-1,-1), 0.3, ZINC700),
        ("TOPPADDING",    (0,0),(-1,-1), 4),
        ("BOTTOMPADDING", (0,0),(-1,-1), 4),
        ("LEFTPADDING",   (0,0),(-1,-1), 6),
        ("RIGHTPADDING",  (0,0),(-1,-1), 6),
        ("VALIGN",        (0,0),(-1,-1), "TOP"),
    ]))
    return t

